{noformat}import {InvoiceExternalIdHelper} from "@server-legacy/common/billing/helper/InvoiceExternalIdHelper";
import {ResponseCodes} from "@server-src/delivery_invoicing/config/ResponseCodes";
import {BoltError} from "@taxify/nodejs-common/lib/async/error/BoltError";
import {BillingDocumentInternalAsyncApi} from "@server-api-async/billing_document/BillingDocumentInternalAsyncApi";
import {UNINVOICEABLE_RECORD_INVOICE_EXTERNAL_ID} from "../table/RecordTable";

export enum UserInvoiceType {
    FOOD = "f",
    DELIVERY = "d"
}

export class DeliveryInvoicingExternalIdHelper {
    public static generateCreditInvoiceExternalId(originalInvoiceExternalId: string) {
        return originalInvoiceExternalId === UNINVOICEABLE_RECORD_INVOICE_EXTERNAL_ID
            ? UNINVOICEABLE_RECORD_INVOICE_EXTERNAL_ID
            : `${originalInvoiceExternalId}-C`;
    }

    public static generateReissueInvoiceExternalId(originalInvoiceExternalId: string) {
        return originalInvoiceExternalId === UNINVOICEABLE_RECORD_INVOICE_EXTERNAL_ID
            ? UNINVOICEABLE_RECORD_INVOICE_EXTERNAL_ID
            : `${originalInvoiceExternalId}-R`;
    }

    public static generateForUserInvoice(
        type: UserInvoiceType,
        cityId: number,
        invoicedEntityId: number, // order ID, suborder ID, user basket ID etc
        fromAgentType: BillingDocumentInternalAsyncApi.InvoiceAgentType // the agent invoicing the user (driver, provider, courier, bolt)
    ) {
        return `${type}-${InvoiceExternalIdHelper.generateForUserInvoice(cityId, invoicedEntityId, fromAgentType)}`;
    }

    public static generateForUserFoodInvoice(
        cityId: number,
        invoicedEntityId: number, // order ID, suborder ID, user basket ID etc
        fromAgentType: BillingDocumentInternalAsyncApi.InvoiceAgentType // the agent invoicing the user (driver, provider, courier, bolt)
    ) {
        return DeliveryInvoicingExternalIdHelper.generateForUserInvoice(
            UserInvoiceType.FOOD,
            cityId,
            invoicedEntityId,
            fromAgentType
        );
    }

    public static generateForUserDeliveryInvoice(
        cityId: number,
        invoicedEntityId: number, // order ID, suborder ID, user basket ID etc
        fromAgentType: BillingDocumentInternalAsyncApi.InvoiceAgentType // the agent invoicing the user (driver, provider, courier, bolt)
    ) {
        return DeliveryInvoicingExternalIdHelper.generateForUserInvoice(
            UserInvoiceType.DELIVERY,
            cityId,
            invoicedEntityId,
            fromAgentType
        );
    }

    public static generateForUserInvoiceRefund(originalInvoiceExternalId: string, refundId: number) {
        const parts = originalInvoiceExternalId.split("-");
        const isPrefixed = DeliveryInvoicingExternalIdHelper.isPrefixedInvoiceExternalId(originalInvoiceExternalId);
        const prefix = isPrefixed ? parts.shift() : "";
        const refundInvoiceExternalId = InvoiceExternalIdHelper.generateForUserInvoiceRefund(parts.join("-"), refundId);

        if (isPrefixed) {
            return `${prefix}-${refundInvoiceExternalId}`;
        }

        return refundInvoiceExternalId;
    }

    public static generateForUserInvoiceFromUserRefundInvoiceExternalId(refundInvoiceExternalId: string) {
        const parts = refundInvoiceExternalId.split("-");
        // Make sure that we support both old and new (prefixed with "d-", or "f-") format.
        const isPrefixed = DeliveryInvoicingExternalIdHelper.isPrefixedInvoiceExternalId(refundInvoiceExternalId);
        const prefix = isPrefixed ? parts.shift() : "";
        const originalInvoiceExternalId = InvoiceExternalIdHelper.generateForUserInvoiceFromUserRefundInvoiceExternalId(
            parts.join("-")
        );

        if (isPrefixed) {
            return `${prefix}-${originalInvoiceExternalId}`;
        }

        return originalInvoiceExternalId;
    }

    private static isPrefixedInvoiceExternalId(externalId: string): boolean {
        return (
            externalId.startsWith(`${UserInvoiceType.FOOD}-`) || externalId.startsWith(`${UserInvoiceType.DELIVERY}-`)
        );
    }

    // NB: will only work with the newest 5-part format of refund invoice external ID-s. previous formats include:
    // * 4-part with no refund event id suffix
    // * 3-part with no invoice type prefix
    // * uuidv4 generated
    public static parseEaterRefundInvoiceExternalId(invoiceExternalId: string): EaterRefundInvoiceExternalIdComponents {
        if (InvoiceExternalIdHelper.isExternalIdUuidV4(invoiceExternalId)) {
            throw BoltError.errorWithData(ResponseCodes.INVALID_INVOICE_EXTERNAL_ID, {
                text: "old format for eater refund invoice external ID",
                invoice_external_id: invoiceExternalId
            });
        }
        const parts: string[] = invoiceExternalId.split("-");
        if (![4, 5].includes(parts?.length)) {
            throw BoltError.errorWithData(ResponseCodes.INVALID_INVOICE_EXTERNAL_ID, {
                text: "invalid format for eater refund invoice external ID",
                invoice_external_id: invoiceExternalId
            });
        }
        return {
            invoice_type: parts[0] as UserInvoiceType,
            city_id: Number(parts[1]),
            agent_id: Number(parts[2]),
            agent_type: parts[3] as BillingDocumentInternalAsyncApi.InvoiceAgentType
        };
    }
}

export interface EaterRefundInvoiceExternalIdComponents {
    city_id: number;
    agent_id: number;
    agent_type: BillingDocumentInternalAsyncApi.InvoiceAgentType;
    invoice_type: UserInvoiceType;
}
